
-- CortexOps SYNTHETIC FINTECH DATASET
-- 100% fictional/synthetic data. PostgreSQL-compatible.
-- Designed for CortexOps agentic-AI prototyping: RAG, tool calling, policy evaluation,
-- anomaly detection, workflow orchestration, audit trails and demo simulations.
-- IMPORTANT: This is NOT an LLM training dataset by itself. It is structured application
-- data that an LLM can query/use through tools or RAG. Fine-tuning would need instruction/
-- response examples separately.

DROP TABLE IF EXISTS audit_logs, agent_tasks, documents, financial_transactions,
existing_loans, applications, policies, products, customers CASCADE;

CREATE TABLE customers (
 customer_id VARCHAR(20) PRIMARY KEY, full_name VARCHAR(120), age INT, city VARCHAR(50),
 employment_type VARCHAR(30), employer VARCHAR(120), employment_years NUMERIC(5,2),
 monthly_income NUMERIC(14,2), declared_monthly_income NUMERIC(14,2), credit_score INT,
 kyc_status VARCHAR(20), customer_since DATE);

CREATE TABLE products (
 product_id VARCHAR(20) PRIMARY KEY, product_name VARCHAR(60), min_amount NUMERIC(14,2),
 max_amount NUMERIC(14,2), min_income NUMERIC(14,2), min_tenure_months INT, max_tenure_months INT);

CREATE TABLE policies (
 policy_id VARCHAR(30) PRIMARY KEY, product_id VARCHAR(20), rule_name VARCHAR(50),
 rule_value NUMERIC(14,4), description TEXT);

CREATE TABLE applications (
 application_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(20), product_id VARCHAR(20),
 requested_amount NUMERIC(14,2), requested_tenure_months INT, purpose VARCHAR(100),
 application_date DATE, status VARCHAR(30), risk_band VARCHAR(20), policy_result VARCHAR(30),
 human_review_required BOOLEAN, anomaly_flag BOOLEAN);

CREATE TABLE existing_loans (
 loan_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(20), loan_type VARCHAR(50),
 original_amount NUMERIC(14,2), outstanding_amount NUMERIC(14,2), emi NUMERIC(14,2),
 start_date DATE, status VARCHAR(20), missed_payments INT);

CREATE TABLE financial_transactions (
 transaction_id VARCHAR(40) PRIMARY KEY, customer_id VARCHAR(20), transaction_date DATE,
 transaction_type VARCHAR(30), amount NUMERIC(14,2), merchant VARCHAR(120),
 category VARCHAR(50), description TEXT, is_salary_credit BOOLEAN, anomaly_flag BOOLEAN);

CREATE TABLE documents (
 document_id VARCHAR(40) PRIMARY KEY, application_id VARCHAR(30), document_type VARCHAR(50),
 document_date DATE, extracted_monthly_income NUMERIC(14,2), extracted_employer VARCHAR(120),
 verification_status VARCHAR(30), consistency_flag BOOLEAN, extraction_notes TEXT);

CREATE TABLE agent_tasks (
 task_id VARCHAR(40) PRIMARY KEY, application_id VARCHAR(30), task_type VARCHAR(60),
 assigned_agent VARCHAR(60), status VARCHAR(30), priority VARCHAR(20),
 result_summary TEXT, created_at TIMESTAMP);

CREATE TABLE audit_logs (
 log_id VARCHAR(40) PRIMARY KEY, application_id VARCHAR(30), agent_name VARCHAR(60),
 action VARCHAR(100), evidence TEXT, outcome VARCHAR(100), created_at TIMESTAMP);

CREATE INDEX idx_apps_customer ON applications(customer_id);
CREATE INDEX idx_tx_customer_date ON financial_transactions(customer_id, transaction_date);
CREATE INDEX idx_loans_customer ON existing_loans(customer_id);
CREATE INDEX idx_docs_application ON documents(application_id);
CREATE INDEX idx_tasks_application ON agent_tasks(application_id);
CREATE INDEX idx_audit_application ON audit_logs(application_id);

